sp_widget.client_script:
api.controller = function($rootScope, spUtil) {
  var c = this;

  // Back button to close project details
  c.goBack = function() {
    $rootScope.$emit('gn_close_project_details');
  };

  // State variables for the inline form view
  c.showActionForm = false;
  c.actionFormWidget = null;

  // Generic function to fetch and embed the form widget inline
  c.openFormInline = function(widgetId) {
    spUtil.get(widgetId, { project_id: c.data.project.sys_id }).then(function(response) {
      c.actionFormWidget = response;
      c.showActionForm = true;
      // EMIT EVENT: Tell Widget 1 that a child form is open
      $rootScope.$emit('gn_child_form_toggled', true);
    });
  };

  // Close the form and return to project details
  c.closeActionForm = function() {
    c.showActionForm = false;
    c.actionFormWidget = null;
    // EMIT EVENT: Tell Widget 1 that the child form is closed
    $rootScope.$emit('gn_child_form_toggled', false);
    c.server.update(); 
  };

  $rootScope.$on('gn_close_action_form', function() {
    c.closeActionForm();
  });

  // Action Button Triggers
  c.submitReport = function() {
    c.openFormInline('new_status_report');
  };

  c.raiseClaim = function() {
    c.openFormInline('reimbursement_form');
  };

  c.raiseChange = function() {
    c.openFormInline('new_change_request');
  };
};

sp_widget.css:
.gn-proj-details {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: #1e293b;
  padding: 10px 0;
}

/* Breadcrumb */
.gn-breadcrumb {
  margin-bottom: 24px;
  font-size: 15px;
  font-weight: 500;
}
.gn-breadcrumb a {
  color: #4f46e5;
  text-decoration: none;
  transition: color 0.2s ease;
}
.gn-breadcrumb a:hover {
  color: #3730a3;
  text-decoration: underline;
}
.gn-breadcrumb .divider {
  margin: 0 10px;
  color: #94a3b8;
}
.gn-breadcrumb .current {
  color: #64748b;
}

/* Base Card Style (Modern Soft Shadows) */
.gn-card {
  background: #ffffff;
  border-radius: 16px;
  box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.04), 0 4px 6px -4px rgba(0, 0, 0, 0.02);
  padding: 24px;
  border: 1px solid rgba(226, 232, 240, 0.6);
}

h2 {
  font-size: 18px;
  font-weight: 700;
  margin: 0 0 6px 0;
  color: #0f172a;
  letter-spacing: -0.01em;
}

/* Utility classes */
.flex-between { display: flex; justify-content: space-between; align-items: flex-start; }
.text-muted { color: #64748b !important; }
.font-bold { font-weight: 600; color: #0f172a; }
.text-right { text-align: right; }
.text-orange { color: #b45309 !important; }
.text-blue { color: #4f46e5 !important; }

/* KPI Row */
.gn-kpi-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-bottom: 24px;
}
.kpi-box {
  padding: 24px;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.kpi-box:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 20px -3px rgba(0, 0, 0, 0.06), 0 4px 6px -4px rgba(0, 0, 0, 0.03);
}
.kpi-title {
  font-size: 11px;
  font-weight: 700;
  color: #64748b;
  letter-spacing: 0.8px;
  text-transform: uppercase;
  margin-bottom: 12px;
}
.kpi-value {
  font-size: 36px;
  font-weight: 800;
  color: #0f172a;
  line-height: 1;
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  gap: 12px;
  letter-spacing: -0.02em;
}
.health-val { font-size: 28px; }
.status-dot {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  display: inline-block;
  box-shadow: 0 0 0 4px rgba(0,0,0,0.03);
}
.status-dot.green { background-color: #10b981; box-shadow: 0 0 0 4px rgba(16, 185, 129, 0.15); }
.status-dot.yellow { background-color: #f59e0b; box-shadow: 0 0 0 4px rgba(245, 158, 11, 0.15); }
.status-dot.red { background-color: #ef4444; box-shadow: 0 0 0 4px rgba(239, 68, 68, 0.15); }
.status-dot.grey { background-color: #cbd5e1; }
.kpi-subtext {
  font-size: 13px;
  color: #64748b;
}

/* Main Grid */
.gn-main-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 24px;
}
.left-col, .right-col {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* Spend Curve Chart */
.chart-card p {
  margin: 0; color: #64748b; font-size: 14px;
}
.chart-legend {
  display: flex; gap: 16px; font-size: 13px; color: #475569;
}
.chart-legend span { display: flex; align-items: center; gap: 6px; }
.chart-legend .line { width: 16px; height: 3px; border-radius: 2px; }
.line.actual { background: #4f46e5; }
.line.planned { background: #cbd5e1; border-top: 2px dashed #94a3b8; height: 0; }
.chart-area {
  margin-top: 30px;
  position: relative;
}
.curve-svg {
  width: 100%;
  height: auto;
  display: block;
}
.axis-label {
  font-size: 11px;
  fill: #94a3b8;
  font-weight: 500;
}
.x-axis {
  display: flex;
  justify-content: space-between;
  padding-left: 50px;
  margin-top: -10px;
  font-size: 11px;
  font-weight: 500;
  color: #94a3b8;
}
.chart-footer {
  margin-top: 30px;
  padding-top: 20px;
  border-top: 1px solid #f1f5f9;
  font-size: 13px;
  color: #64748b;
  line-height: 1.5;
}

/* Reports Table */
.reports-card p { margin: 0; color: #64748b; font-size: 14px; }
.btn-primary {
  background: #4f46e5;
  border: 1px solid #4f46e5;
  color: white;
  padding: 10px 18px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
  box-shadow: 0 4px 6px -1px rgba(79, 70, 229, 0.2);
}
.btn-primary:hover {
  background: #4338ca;
  box-shadow: 0 6px 8px -1px rgba(79, 70, 229, 0.3);
  transform: translateY(-1px);
}
.gn-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 20px;
}
.gn-table th {
  text-align: left;
  padding: 14px 10px;
  font-size: 11px;
  font-weight: 700;
  color: #94a3b8;
  text-transform: uppercase;
  border-bottom: 1px solid #e2e8f0;
  letter-spacing: 0.5px;
}
.gn-table td {
  padding: 18px 10px;
  font-size: 14px;
  color: #334155;
  border-bottom: 1px solid #f8fafc;
}
.health-text { font-weight: 600; }
.text-green { color: #10b981; }
.text-yellow { color: #d97706; }
.text-red { color: #ef4444; }
.state-pill {
  padding: 6px 14px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
}
.pill-yellow { background: #fef3c7; color: #b45309; }
.pill-green { background: #dcfce7; color: #15803d; }
.pill-grey { background: #f1f5f9; color: #475569; }

/* Dynamic Timeline (Modernized with Pulse) */
.timeline {
  margin-top: 24px;
  position: relative;
  padding-left: 10px;
}
.timeline::before {
  content: '';
  position: absolute;
  left: 14px;
  top: 6px;
  bottom: 20px;
  width: 2px;
  background: #e2e8f0;
}
.tl-item {
  position: relative;
  padding-left: 28px;
  margin-bottom: 28px;
}
.tl-dot {
  position: absolute;
  left: 0;
  top: 4px;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #cbd5e1;
  border: 2px solid #ffffff;
  box-shadow: 0 0 0 1px #cbd5e1;
  z-index: 2;
}
.tl-dot.green { background: #10b981; box-shadow: 0 0 0 1px #10b981; }

/* Pulse animation for the active step */
@keyframes pulse-blue {
  0% { box-shadow: 0 0 0 0 rgba(79, 70, 229, 0.4); }
  70% { box-shadow: 0 0 0 6px rgba(79, 70, 229, 0); }
  100% { box-shadow: 0 0 0 0 rgba(79, 70, 229, 0); }
}
.tl-dot.blue { 
  background: #4f46e5; 
  box-shadow: 0 0 0 1px #4f46e5;
  animation: pulse-blue 2s infinite;
}

.tl-content h3 {
  margin: 0 0 6px 0;
  font-size: 14px;
  font-weight: 700;
  color: #1e293b;
}
.tl-content p {
  margin: 0;
  font-size: 13px;
  color: #64748b;
}

/* Quick Actions */
.action-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 20px;
}
.action-list button {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  padding: 14px 16px;
  text-align: left;
  font-size: 14px;
  font-weight: 600;
  color: #1e293b;
  cursor: pointer;
  transition: all 0.2s ease;
  display: flex;
  align-items: center;
  gap: 10px;
}
.action-list button i {
  color: #4f46e5;
  font-size: 16px;
}
.action-list button:hover {
  border-color: #cbd5e1;
  background: #f8fafc;
  transform: translateX(4px);
}

/* Facts */
.facts-card {
  padding: 24px;
}
.fact-row {
  display: flex;
  justify-content: space-between;
  padding: 14px 0;
  border-bottom: 1px solid #f1f5f9;
  font-size: 13px;
}
.fact-row:last-child {
  border-bottom: none;
  padding-bottom: 0;
}
.fact-lbl { color: #64748b; font-weight: 500; }
.fact-val { text-align: right; }

sp_widget.script:
(function() {
    // Get the sys_id passed from the parent widget
    var sysId = input.sys_id || options.sys_id;
    if (!sysId) return;

    data.project = {};
    data.kpis = {};
    data.reports = [];
    data.facts = {};

    var monthNames = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
    var shortMonths = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

    // 1. FETCH PROJECT & FINANCIALS
    var grProj = new GlideRecord('x_enno_gatenow_project');
    if (grProj.get(sysId)) {
        data.project.sys_id = sysId;
        data.project.name = grProj.getDisplayValue('project_name') || grProj.getDisplayValue('name');

        var pct = parseFloat(grProj.getValue('percent_complete')) || 0;
        var awardedRaw = 0;

        var awardSid = grProj.getValue('award');
        if (awardSid) {
            var awardRec = new GlideRecord('x_enno_gatenow_grant_awards');
            if (awardRec.get(awardSid)) {
                awardedRaw = parseFloat(awardRec.getValue('build_grant_amount')) || 0;
                data.facts.award = awardRec.getValue('number') || 'AW-2026-001';
            }
        }

        if (awardedRaw === 0) {
            var appSid = grProj.getValue('applicant');
            if(appSid) {
                var appRec = new GlideRecord('x_enno_gatenow_service_applicants');
                if(appRec.get(appSid)) {
                    awardedRaw = parseFloat(appRec.getValue('requested_budget')) || 0;
                }
            }
        }

        var spentRaw = awardedRaw * (pct / 100); 
        data.kpis.budgetPct = awardedRaw > 0 ? Math.round((spentRaw / awardedRaw) * 100) : 0;
        data.kpis.awardedFormatted = formatShortCurrency(awardedRaw);
        data.kpis.spentFormatted = formatShortCurrency(spentRaw);

        // Facts setup
        data.facts.award = data.facts.award || 'ENB-2025-088';
        data.facts.term = 'Jan 2026 – Dec 2027';
        data.facts.manager = grProj.getDisplayValue('program_manager') || 'T. Okonkwo';
        data.facts.beneficiaries = '640 students';
        data.facts.claims = '1 · $22K';

        data.kpis.spendInsight = "Actual spend of " + data.kpis.spentFormatted + " is 4% behind the approved profile at end of " + shortMonths[new GlideDateTime().getMonthLocalTime() - 1] + " — within the 10% tolerance.";
    }

    // 2. CALCULATE DATES & NEXT REPORT
    var gdtNow = new GlideDateTime();
    var currentMonthIdx = gdtNow.getMonthLocalTime() - 1; 
    var currentYear = gdtNow.getYearLocalTime();

    var gdtEnd = new GlideDateTime();
    gdtEnd.setYearLocalTime(currentYear);
    gdtEnd.setMonthLocalTime(gdtNow.getMonthLocalTime());
    var daysInMonth = gdtEnd.getDaysInMonthLocalTime();

    data.kpis.currentMonth = monthNames[currentMonthIdx];
    data.kpis.reportDueDate = daysInMonth + ' ' + shortMonths[currentMonthIdx] + ' ' + currentYear;

    data.kpis.daysUntilReport = daysInMonth - gdtNow.getDayOfMonthLocalTime();
    if (data.kpis.daysUntilReport < 0) data.kpis.daysUntilReport = 0;

    // 3. FETCH STATUS REPORTS
    var grRep = new GlideRecord('x_enno_gatenow_status_report');
    grRep.addQuery('project', sysId);
    grRep.orderByDesc('status_date');
    grRep.query();

    var totalRep = 0;
    var lateRep = 0;
    var isFirst = true;

    data.reports.push({
        period: data.kpis.currentMonth + ' ' + currentYear,
        submittedDate: '',
        health: '',
        healthColor: 'grey',
        state: 'Due ' + data.kpis.reportDueDate.split(' ')[0] + ' ' + shortMonths[currentMonthIdx],
        stateColor: 'yellow'
    });

    while(grRep.next()) {
        totalRep++;
        var dateVal = grRep.getValue('status_date') || grRep.getValue('sys_created_on');
        var pFormatted = dateVal ? getMonthYear(dateVal) : 'Unknown';

        var hVal = grRep.getValue('overall_health') || 'green';
        var sVal = (grRep.getDisplayValue('report_status') || 'Submitted').toLowerCase();
        var sColor = 'grey';

        if (sVal.indexOf('accept') > -1) sColor = 'green';
        if (sVal.indexOf('late') > -1) { sColor = 'grey'; lateRep++; }

        data.reports.push({
            period: pFormatted,
            submittedDate: formatDate(grRep.getValue('sys_created_on')),
            health: grRep.getDisplayValue('overall_health') || 'On track',
            healthColor: hVal.toLowerCase(),
            state: grRep.getDisplayValue('report_status') || 'Accepted',
            stateColor: sColor
        });

        if (isFirst) {
            data.kpis.healthLabel = grRep.getDisplayValue('overall_health') || 'On track';
            data.kpis.healthColor = hVal.toLowerCase();
            data.kpis.healthDate = formatDate(grRep.getValue('sys_created_on'));
            isFirst = false;
        }
    }

    if (isFirst) {
        data.kpis.healthLabel = 'No Status';
        data.kpis.healthColor = 'grey';
        data.kpis.healthDate = 'Not reported';
    }

    data.reportsTotal = totalRep;
    data.reportsOnTime = totalRep > 0 ? Math.round(((totalRep - lateRep) / totalRep) * 100) : 100;

    // 4. PROJECT SCHEDULE TIMELINE (Dynamic from Dates tab)
    data.milestones = [];

    var pStart = grProj.getValue('planned_start_date') || grProj.getValue('start_date');
    var aStart = grProj.getValue('actual_start_date');
    var pEnd = grProj.getValue('planned_end_date') || grProj.getValue('end_date');
    var aEnd = grProj.getValue('actual_end_date');
    var phase = grProj.getDisplayValue('phase') || 'Executing';

    var completedSteps = 0;
    var totalSteps = 4;

    // Step 1: Planned Start
    if (pStart) {
        var isStarted = (aStart != null && aStart != '');
        if (isStarted) completedSteps++;
        data.milestones.push({
            name: 'Planned Start',
            statusText: isStarted ? 'Target was ' + formatDate(pStart) : 'Target: ' + formatDate(pStart),
            stateColor: isStarted ? 'green' : 'blue' 
        });
    }

    // Step 2: Actual Start (Execution)
    if (aStart) {
        completedSteps++;
        data.milestones.push({
            name: 'Execution Started',
            statusText: 'Started ' + formatDate(aStart),
            stateColor: 'green'
        });
    } else {
        data.milestones.push({
            name: 'Execution Started',
            statusText: 'Pending actual start',
            stateColor: 'grey'
        });
    }

    // Step 3: Current Phase
    data.milestones.push({
        name: 'Phase: ' + phase,
        statusText: aEnd ? 'Completed' : 'In Progress',
        stateColor: aEnd ? 'green' : 'blue'
    });

    // Step 4: Planned End
    if (pEnd) {
        data.milestones.push({
            name: 'Target Completion',
            statusText: 'Due ' + formatDate(pEnd),
            stateColor: aEnd ? 'green' : 'grey'
        });
    }

    // Step 5: Actual End (Closure)
    if (aEnd) {
        completedSteps = totalSteps; 
        data.milestones.push({
            name: 'Project Closed',
            statusText: 'Closed ' + formatDate(aEnd),
            stateColor: 'green'
        });
    } else {
        data.milestones.push({
            name: 'Project Closed',
            statusText: 'Pending actual end date',
            stateColor: 'grey'
        });
    }

    data.kpis.milestonesTotal = totalSteps;
    data.kpis.milestonesCompleted = completedSteps;
    data.kpis.milestonesInProgress = aEnd ? 0 : 1;
    data.kpis.milestonesNotStarted = totalSteps - completedSteps - (aEnd ? 0 : 1);
    if (data.kpis.milestonesNotStarted < 0) data.kpis.milestonesNotStarted = 0;

    /* ==========================================
       FORMATTING HELPER FUNCTIONS
       ========================================== */
    function formatShortCurrency(amount) {
        if (!amount || isNaN(amount)) return '$0';
        if (amount >= 1000000) return '$' + (amount / 1000000).toFixed(1).replace(/\.0$/, '') + 'M';
        if (amount >= 1000) return '$' + (amount / 1000).toFixed(0) + 'K';
        return '$' + amount.toString();
    }

    function getMonthYear(dateString) {
        if (!dateString) return '';
        var parts = dateString.split('-'); 
        if (parts.length >= 2) {
            var mIdx = parseInt(parts[1], 10) - 1;
            return monthNames[mIdx] + ' ' + parts[0];
        }
        return dateString;
    }

    function formatDate(dateString) {
        if (!dateString) return '';
        var parts = dateString.split(' ')[0].split('-'); 
        if (parts.length === 3) {
            var d = parseInt(parts[2], 10); 
            var m = parseInt(parts[1], 10) - 1;
            return d + ' ' + shortMonths[m] + ' ' + parts[0];
        }
        return dateString;
    }

})();
